  "claims": [
    {
      "card_ids": ["C32"],
      "claim": "Trazodone, a heteroaromatic drug with a very high assay-transfer score, has absolute oral bioavailability averaging 70–90% in humans, supporting high F for the query.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C28"],
      "claim": "Alprazolam, a triazolobenzodiazepine with high transferability, has absolute oral bioavailability of 0.92 in humans, well above the 20% threshold.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C48"],
      "claim": "Netupitant, a lipophilic heteroaromatic drug, has high absolute oral bioavailability of 63–87% in humans, supporting high F.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C19"],
      "claim": "Flibanserin, despite moderate first-pass metabolism, has absolute oral bioavailability of about 46%, still clearly above the 20% threshold.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C01"],
      "claim": "Triazolam, a close structural relative of alprazolam, has absolute oral bioavailability of about 55% in humans, supporting high F.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C47"],
      "claim": "Tolfenamic acid, an oral NSAID with a carboxylic acid, has absolute bioavailability averaging 60% in healthy volunteers, supporting high F.",
      "evidence_role": "supportive"
    }
  ],
  "confidence": "high",
  "decision_summary": "All transferred experimental evidence points to oral bioavailability well above 20%; multiple absolute human F values range from roughly 33–100%, with no record below the threshold. The query's small heteroaromatic pyrazolone structure is consistent with these high-oral-availability analogues.",
  "evidence_gaps": [
    "No direct absolute bioavailability measurement for the query molecule itself; prediction relies on high-transfer analogues.",
    "Some records report unspecified rather than absolute bioavailability, but all reported values remain above the 20% threshold."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

